export default meta;

type Story = StoryObj<typeof DesignView>;

const frame = (node: React.ReactNode) => <div className="h-96 w-3xl rounded-md border border-border bg-card text-foreground shadow-sm">{node}</div>;

export const Default: Story = {
  args: {
